#!/usr/bin/env node
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

export const BANNER =
  "<!-- GENERATED by scripts/build-html.mjs from src/partials/*.html — do not edit -->";

export function listPartials(partialsDir) {
  return fs
    .readdirSync(partialsDir)
    .filter((name) => name.endsWith(".html"))
    .sort();
}

export function renderHtml(partialsDir, version) {
  const files = listPartials(partialsDir);
  if (files.length === 0) {
    throw new Error(`No partials found in ${partialsDir}`);
  }

  const raws = files.map((name) => fs.readFileSync(path.join(partialsDir, name), "utf8"));
  const eol = raws[0].includes("\r\n") ? "\r\n" : "\n";
  const normalize = (text) => {
    const lf = text.replace(/\r\n?/g, "\n");
    return eol === "\n" ? lf : lf.replace(/\n/g, "\r\n");
  };

  const body = raws
    .map(normalize)
    .join("")
    .replaceAll("{{APP_VERSION}}", version)
    .replaceAll("{{ASSET_V}}", version);

  const leftover = body.match(/\{\{[A-Z0-9_]+\}\}/);
  if (leftover) {
    throw new Error(`Unreplaced placeholder in partials: ${leftover[0]}`);
  }

  const doctype = `<!DOCTYPE html>${eol}`;
  if (!body.startsWith(doctype)) {
    throw new Error("src/partials/00-doc-head.html must start with <!DOCTYPE html>");
  }

  const html = doctype + BANNER + eol + body.slice(doctype.length);
  if (!html.endsWith(eol)) {
    throw new Error("Generated HTML must end with a newline (check 90-tail.html)");
  }
  return html;
}

export function buildHtml(root = process.cwd()) {
  const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
  const html = renderHtml(path.join(root, "src", "partials"), pkg.version);
  const outputPath = path.join(root, "index.html");
  const previous = fs.existsSync(outputPath) ? fs.readFileSync(outputPath, "utf8") : "";
  if (previous === html) {
    return { html, changed: false, version: pkg.version };
  }
  fs.writeFileSync(outputPath, html);
  return { html, changed: true, version: pkg.version };
}

const invokedDirectly =
  process.argv[1] && pathToFileURL(process.argv[1]).href === import.meta.url;

if (invokedDirectly) {
  const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
  const { changed, version } = buildHtml(root);
  const count = listPartials(path.join(root, "src", "partials")).length;
  console.log(
    changed
      ? `index.html written from ${count} partials (v${version})`
      : `index.html up to date (${count} partials, v${version})`,
  );
}
